    <header><div><h2 id="advance-title-{{ $payment->id }}">Advance details</h2><p>{{ $payment->full_name }} · {{ $payment->currency }} {{ number_format($payment->amount_cents/100,2) }} · {{ $payment->paid_on }}</p></div><button class="sa-manage" type="button" data-advance-close aria-label="Close advance actions"><ion-icon name="close-outline" aria-hidden="true"></ion-icon></button></header>
    <section><h3>Payment reference</h3><p class="sa-full-reference">{{ $payment->reference }}</p><p>{{ $payment->bank_name ?: 'Cash' }}</p>@if($payment->status === 'reversed')<p>Reversed {{ $payment->reversed_on }} · {{ $payment->reversal_reason }}</p>@endif</section>
