    @if($canReverse)<section class="sa-reversal"><h3>Reverse payment</h3><p>Use this to correct an incorrect payment record. The original and its reversal remain in the audit history.</p><form method="post" action="/payroll/payments/{{ $payment->id }}/reverse" data-confirm="Reverse this payment? The original record will remain in the audit history.">@csrf<input type="hidden" name="_advance_action_id" value="{{ $payment->id }}"><div class="pr-field"><label for="reverse-date-{{ $payment->id }}">Reversal date</label><input id="reverse-date-{{ $payment->id }}" name="date" type="date" max="{{ date('Y-m-d') }}" value="{{ old('_advance_action_id') == $payment->id ? old('date',date('Y-m-d')) : date('Y-m-d') }}" required></div><div class="pr-field"><label for="reverse-reason-{{ $payment->id }}">Reason</label><textarea id="reverse-reason-{{ $payment->id }}" name="reason" minlength="5" maxlength="1000" rows="2" required>{{ old('_advance_action_id') == $payment->id ? old('reason') : '' }}</textarea></div><button class="pr-btn pr-btn-danger" type="submit">Confirm reversal</button></form></section>@endif
